  "claim": {
    "component_id": "C021.component",
    "value": "Introducing a readiness-and-collection handoff is a candidate change for the selected stage.",
    "scope": "An example for the day-14 choice, conditional on findings and feasibility within existing equipment and staffing; its detailed design is unspecified.",
    "provenance": {
      "refs": [
        {"source_id": "P011", "role": "CONTEXT"},
        {"source_id": "P012", "role": "SUPPORT"},
        {"source_id": "P013", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly identifies this candidate change and its findings and feasibility conditions."
    }
  },
  "signal_basis": {
    "component_id": "C021.signal_basis",
    "value": "Recurring readiness delays despite calendar availability, or repeated late collection after documented readiness, identify a candidate stage when delays recur on multiple booking days in each investigation week and that stage has the greatest documented delay burden in both weeks.",
    "scope": "Assumed observations during the two-week investigation, with sufficient bookings and missing records unable to reverse the ranking. The persistence rule supports practical selection without statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {"source_id": "P011", "role": "SUPPORT"},
        {"source_id": "P014", "role": "SUPPORT"},
        {"source_id": "P017", "role": "SUPPORT"},
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P025", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the relevant stage-specific signals, persistence criterion, evidence limitations and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required to warrant the bounded candidate-change claim."
    }
  },
  "rationale": "Repeated delays at the relevant readiness or collection stage license considering a handoff change aimed at that stage. The claim establishes candidacy conditional on findings and feasibility; it does not assert that the handoff will reduce late starts.",
  "uncertainty": "The handoff's detailed design and effectiveness remain undetermined, which is consistent with its stated status as a candidate.",
  "anomalies": []
}
